package qes

import (
	"math/big"
)

// GOST R 34.10-2012: checking a signature on an elliptic curve y² = x³ + ax + b mod p, with the subgroup of order q
// generated by (x, y). Only the check: go24 never signs with a qualified key, the signer's tool does.

type curve struct{ p, q, a, b, x, y *big.Int }

// point is an affine point; nil is the point at infinity.
type point struct{ x, y *big.Int }

func curveOf(oid string) *curve {
	h, ok := curveParams[oid]
	if !ok {
		return nil
	}
	var v [6]*big.Int
	for i := range h {
		v[i], _ = new(big.Int).SetString(h[i], 16)
	}
	return &curve{v[0], v[1], v[2], v[3], v[4], v[5]}
}

// size is the bytes of a coordinate: 32 or 64.
func (c *curve) size() int { return (c.q.BitLen() + 7) / 8 }

func (c *curve) on(pt *point) bool {
	l := new(big.Int).Mul(pt.y, pt.y)
	r := new(big.Int).Mul(pt.x, pt.x)
	r.Add(r, c.a).Mul(r, pt.x).Add(r, c.b)
	return l.Sub(l, r).Mod(l, c.p).Sign() == 0
}

func (c *curve) add(p1, p2 *point) *point {
	if p1 == nil {
		return p2
	}
	if p2 == nil {
		return p1
	}
	var l *big.Int
	if p1.x.Cmp(p2.x) == 0 {
		if sum := new(big.Int).Add(p1.y, p2.y); sum.Mod(sum, c.p).Sign() == 0 {
			return nil // P + (−P)
		}
		num := new(big.Int).Mul(p1.x, p1.x) // (3x² + a) / 2y
		num.Mul(num, big.NewInt(3)).Add(num, c.a)
		den := new(big.Int).Lsh(p1.y, 1)
		l = num.Mul(num, den.ModInverse(den.Mod(den, c.p), c.p))
	} else {
		num := new(big.Int).Sub(p2.y, p1.y) // (y2 − y1) / (x2 − x1)
		den := new(big.Int).Sub(p2.x, p1.x)
		l = num.Mul(num, den.ModInverse(den.Mod(den, c.p), c.p))
	}
	l.Mod(l, c.p)
	x := new(big.Int).Mul(l, l)
	x.Sub(x, p1.x).Sub(x, p2.x).Mod(x, c.p)
	y := new(big.Int).Sub(p1.x, x)
	y.Mul(y, l).Sub(y, p1.y).Mod(y, c.p)
	return &point{x, y}
}

func (c *curve) mul(k *big.Int, pt *point) *point {
	var r *point
	for i := k.BitLen() - 1; i >= 0; i-- {
		r = c.add(r, r)
		if k.Bit(i) == 1 {
			r = c.add(r, pt)
		}
	}
	return r
}

// verify checks the signature s‖r (big-endian, as CMS and certificates keep it) of the digest e (a big-endian
// number: the Streebog digest reversed) by the public key.
func (c *curve) verify(pub *point, e *big.Int, sig []byte) bool {
	n := c.size()
	if len(sig) != 2*n || pub == nil || !c.on(pub) {
		return false
	}
	s, r := new(big.Int).SetBytes(sig[:n]), new(big.Int).SetBytes(sig[n:])
	if r.Sign() <= 0 || r.Cmp(c.q) >= 0 || s.Sign() <= 0 || s.Cmp(c.q) >= 0 {
		return false
	}
	e = new(big.Int).Mod(e, c.q)
	if e.Sign() == 0 {
		e.SetInt64(1)
	}
	v := new(big.Int).ModInverse(e, c.q)
	z1 := new(big.Int).Mul(s, v)
	z1.Mod(z1, c.q)
	z2 := new(big.Int).Mul(r, v)
	z2.Sub(c.q, z2.Mod(z2, c.q))
	pt := c.add(c.mul(z1, &point{c.x, c.y}), c.mul(z2, pub))
	return pt != nil && new(big.Int).Mod(pt.x, c.q).Cmp(r) == 0
}

// le is a little-endian number, as GOST keys and digests are kept.
func le(b []byte) *big.Int {
	r := make([]byte, len(b))
	for i := range b {
		r[len(b)-1-i] = b[i]
	}
	return new(big.Int).SetBytes(r)
}
